// Java Reference Implementation
public void put(K key, V val) {
    int idx = index(key);
    Node<K, V> curr = buckets[idx];
    while (curr != null) {
        if (Objects.equals(curr.key, key)) {
            curr.val = val;
            return;
        }
        curr = curr.next;
    }
    Node<K, V> node = new Node<>(key, val);
    node.next = buckets[idx];
    buckets[idx] = node;
}

